SELECT ITEM_VALUE_EN id, ITEM_VALUE_EN text FROM OPICS_PARAM
PARA_TYPE = #{type}
AND ITEM_VALUE_EN LIKE CONCAT('%',CONCAT(#{search},'%'))
AND ITEM_ID = #{initValue}

SELECT FINPROD_MARKET_ID id, FINPROD_NAME text, FINPROD_ID object FROM FIN_PRODUCT
FINPROD_TYPE2 = #{finprodType2}
AND (FINPROD_MARKET_ID LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%') OR FINPROD_NAME LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%'))
AND FINPROD_MARKET_ID = #{initValue}
AND FIN_PRODUCT.FINPROD_TYPE2 in ('F01','F06','F10')

SELECT 
	FINPROD_MARKET_ID id,
	FINPROD_NAME text,
	FINPROD_ID object
FROM
	FIN_PRODUCT

	FINPROD_TYPE2 = #{finprodType2}

		AND (FINPROD_MARKET_ID LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%') 
		OR FINPROD_NAME LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%'))


		AND FINPROD_MARKET_ID = #{initValue}


		AND  EXISTS ( SELECT 1 FROM FIN_CASH_CALC_RULE FCCR
		INNER JOIN ( SELECT * FROM ( SELECT FIN_CASH_INFO.*,ROW_NUMBER()
		OVER(PARTITION BY FINPROD_ID ORDER BY UPDATE_TIME DESC)
		rn  FROM FIN_CASH_INFO where 1 = 1

			and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}


			AND FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}

		) T  WHERE  T.RN <= 1 ) FCI
		ON FCCR.CASH_ID = FCI.CASH_ID
		WHERE    fci.FINPROD_ID = FIN_PRODUCT.finprod_id
		and  TO_CHAR(FCCR.EFF_DATE,'yyyy-MM-dd')   <=
			CASE WHEN (SELECT
			VDATE
			FROM FIN_PRODUCT
			WHERE FINPROD_MARKET_ID = #{initValue}
			) >= TO_DATE(#{platDate},'yyyy-MM-dd')
			THEN (SELECT
			TO_CHAR(VDATE,'yyyy-MM-dd')
			FROM FIN_PRODUCT
			WHERE FINPROD_MARKET_ID = #{initValue}
			)
			ELSE #{platDate} END
		)

	AND FIN_PRODUCT.FINPROD_TYPE2 not in ('F01','F06','F10')

SELECT TRADER
FROM ETR_DISTRIBUTE


		AND ENTRUST_ID = #{entrustId}


		AND REC_STATUS = #{entrustStatus}

